import{_ as l,C as n,o as e,c as t,a2 as o,b as s,w as i,a as d,E as c,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const P=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_3.md"}'),m={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_3.md"};function p(g,a,b,f,h,E){const r=n("Mermaid");return e(),t("div",null,[a[1]||(a[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI)&quot;">​</a></h2><h3 id="eje-tematico-elaboracion-de-manuales-de-usuario-y-manual-del-sistema" tabindex="-1">Eje Temático: Elaboración de Manuales de Usuario y Manual del Sistema <a class="header-anchor" href="#eje-tematico-elaboracion-de-manuales-de-usuario-y-manual-del-sistema" aria-label="Permalink to &quot;Eje Temático: Elaboración de Manuales de Usuario y Manual del Sistema&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-sostenibilidad-a-traves-de-la-documentacion" tabindex="-1">🧭 Introducción: La Sostenibilidad a Través de la Documentación <a class="header-anchor" href="#🧭-introduccion-la-sostenibilidad-a-traves-de-la-documentacion" aria-label="Permalink to &quot;🧭 Introducción: La Sostenibilidad a Través de la Documentación&quot;">​</a></h2><p>Un error fatal en proyectos informáticos estudiantiles es entregar el software funcionando pero sin documentación técnica. Cuando los estudiantes se gradúan o se retiran de la comunidad, nadie sabe cómo instalar el sistema en una computadora nueva, cómo cambiar la clave del administrador o cómo restaurar una copia de seguridad si el disco duro se daña. En consecuencia, el sistema se abandona.</p><p>Para evitar esto, el estándar del PNFI exige la elaboración de <strong>dos manuales formales e independientes</strong>, diseñados para dos audiencias completamente distintas:</p><ol><li><strong>El Manual de Usuario:</strong> Dirigido a secretarias, voceros y operadores no técnicos que usan la aplicación a diario.</li><li><strong>El Manual del Sistema (o del Administrador/Técnico):</strong> Dirigido a ingenieros, técnicos de soporte o futuros estudiantes del PNFI que deben dar mantenimiento, modificar el código fuente o reinstalar los servidores.</li></ol>',8)),(e(),s(u,null,{default:i(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20DOC%5B%22%F0%9F%93%9A%20Documentaci%C3%B3n%20T%C3%A9cnica%20de%20PST%20II%22%5D%0A%20%20%20%20DOC%20--%3E%20MU%5B%22%F0%9F%91%A4%20MANUAL%20DE%20USUARIO%3Cbr%3E%E2%80%A2%20Lenguaje%20cotidiano%20y%20amigable%3Cbr%3E%E2%80%A2%20Capturas%20de%20pantalla%20paso%20a%20paso%3Cbr%3E%E2%80%A2%20Soluci%C3%B3n%20a%20dudas%20frecuentes%22%5D%0A%20%20%20%20DOC%20--%3E%20MS%5B%22%E2%9A%99%EF%B8%8F%20MANUAL%20DEL%20SISTEMA%3Cbr%3E%E2%80%A2%20Arquitectura%20y%20diagrama%20de%20despliegue%3Cbr%3E%E2%80%A2%20Configuraci%C3%B3n%20de%20servidores%20y%20BD%3Cbr%3E%E2%80%A2%20Diccionario%20de%20datos%20y%20c%C3%B3digo%20fuente%3Cbr%3E%E2%80%A2%20Pol%C3%ADticas%20de%20Backup%20y%20Restore%22%5D%0A%0A%20%20%20%20style%20DOC%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20MU%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20MS%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<hr><h2 id="👤-capitulo-i-estructura-del-manual-de-usuario" tabindex="-1">👤 CAPÍTULO I: Estructura del Manual de Usuario <a class="header-anchor" href="#👤-capitulo-i-estructura-del-manual-de-usuario" aria-label="Permalink to &quot;👤 CAPÍTULO I: Estructura del Manual de Usuario&quot;">​</a></h2><p>El Manual de Usuario debe redactarse pensando en una persona que no tiene conocimientos de programación ni de bases de datos.</p><h3 id="_1-1-estructura-estandar-del-manual-de-usuario" tabindex="-1">1.1 Estructura Estándar del Manual de Usuario <a class="header-anchor" href="#_1-1-estructura-estandar-del-manual-de-usuario" aria-label="Permalink to &quot;1.1 Estructura Estándar del Manual de Usuario&quot;">​</a></h3><ol><li><strong>Portada Institucional:</strong> Nombre del sistema, versión, fecha de edición y logotipo de la comunidad / UPTT.</li><li><strong>Introducción y Objetivos:</strong> Explicación sencilla de qué beneficios aporta el sistema a la comunidad.</li><li><strong>Requerimientos del Entorno de Trabajo:</strong> Navegadores recomendados (Mozilla Firefox, Chromium), resolución de pantalla sugerida y cómo encender el equipo.</li><li><strong>Acceso al Sistema:</strong><ul><li>Cómo abrir el navegador e ingresar a la URL local (ej: <code>http://localhost/sistema_censo</code> o <code>http://192.168.1.100/censo</code>).</li><li>Pantalla de inicio de sesión, ingreso de credenciales y qué hacer si olvida su clave.</li></ul></li><li><strong>Navegación por el Sistema (Módulo por Módulo):</strong><ul><li>Descripción de la barra de menús.</li><li><strong>Guía paso a paso ilustrada con capturas de pantalla reales</strong>: <ul><li><em>Paso 1: Presione el botón &#39;Nuevo Habitante&#39;.</em></li><li><em>Paso 2: Rellene los campos obligatorios marcados con asterisco (</em>).*</li><li><em>Paso 3: Haga clic en &#39;Guardar&#39;. Observe el mensaje de confirmación verde.</em></li></ul></li></ul></li><li><strong>Manejo de Errores y Mensajes de Alerta:</strong> Explicación de los mensajes que muestra el sistema (ej: &quot;La cédula ya existe&quot;, &quot;Debe llenar el campo teléfono&quot;).</li><li><strong>Preguntas Frecuentes (FAQ) y Glosario Comunitario.</strong></li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Regla de Usabilidad en Capturas:</strong> Toda captura de pantalla en el Manual de Usuario debe tener flechas rojas, recuadros o llamadas numéricas (1, 2, 3) que destaquen con exactitud el botón o campo que el usuario debe presionar.</p></div><hr><h2 id="⚙️-capitulo-ii-estructura-del-manual-del-sistema-administrador" tabindex="-1">⚙️ CAPÍTULO II: Estructura del Manual del Sistema (Administrador) <a class="header-anchor" href="#⚙️-capitulo-ii-estructura-del-manual-del-sistema-administrador" aria-label="Permalink to &quot;⚙️ CAPÍTULO II: Estructura del Manual del Sistema (Administrador)&quot;">​</a></h2><p>El Manual del Sistema es el documento de ingeniería que describe la arquitectura interna y los procedimientos técnicos de administración.</p><h3 id="_2-1-estructura-estandar-del-manual-del-sistema" tabindex="-1">2.1 Estructura Estándar del Manual del Sistema <a class="header-anchor" href="#_2-1-estructura-estandar-del-manual-del-sistema" aria-label="Permalink to &quot;2.1 Estructura Estándar del Manual del Sistema&quot;">​</a></h3><ol><li><strong>Ficha Técnica del Software:</strong><ul><li>Nombre de la aplicación, versión (ej: <code>v1.0.0</code>), tipo de licencia (GPL v3) y tecnologías utilizadas (lenguaje, framework, motor de BD).</li></ul></li><li><strong>Requerimientos de Hardware y Software del Servidor:</strong><ul><li>Mínimos: CPU Dual Core 2.0 GHz, 2 GB RAM, 20 GB de disco disponible.</li><li>Recomendados: CPU Quad Core, 4 GB RAM, unidad de estado sólido (SSD).</li><li>Sistema Operativo recomendado: Debian GNU/Linux, Ubuntu Server o similar.</li></ul></li><li><strong>Diagrama de Despliegue (UML Deployment Diagram):</strong><ul><li>Muestra cómo interactúan el nodo cliente (navegador web), el nodo servidor web (Apache/Nginx) y el nodo servidor de base de datos (PostgreSQL/MariaDB).</li></ul></li><li><strong>Guía de Instalación y Configuración Paso a Paso:</strong><ul><li>Comandos de terminal para clonar el repositorio e instalar dependencias.</li><li>Configuración del archivo de entorno (ej: <code>.env</code> con credenciales de base de datos).</li><li>Comandos para ejecutar las migraciones y sembrar los datos iniciales (<code>seeders</code>).</li></ul></li><li><strong>Estructura del Proyecto y Código Fuente:</strong><ul><li>Árbol de carpetas del proyecto explicando la responsabilidad de cada directorio (<code>/controllers</code>, <code>/models</code>, <code>/views</code>, <code>/config</code>, <code>/public</code>).</li></ul></li><li><strong>Diccionario de Datos y Modelo Físico de Base de Datos:</strong><ul><li>Tablas, campos, tipos de datos, claves primarias y foráneas.</li></ul></li><li><strong>Procedimiento de Respaldos (Backup) y Restauración (Restore):</strong><ul><li>Comandos exactos para respaldar la base de datos (ej: <code>pg_dump</code> o <code>mysqldump</code>).</li><li>Programación de respaldos automáticos mediante tareas programadas (<code>cron</code> en Linux o Programador de Tareas en Windows).</li><li>Procedimiento de contingencia para restaurar la base de datos ante una falla de disco.</li></ul></li></ol><hr><h2 id="⚖️-capitulo-iii-licenciamiento-de-software-libre-en-la-documentacion" tabindex="-1">⚖️ CAPÍTULO III: Licenciamiento de Software Libre en la Documentación <a class="header-anchor" href="#⚖️-capitulo-iii-licenciamiento-de-software-libre-en-la-documentacion" aria-label="Permalink to &quot;⚖️ CAPÍTULO III: Licenciamiento de Software Libre en la Documentación&quot;">​</a></h2><p>Tanto en el código fuente como en los manuales, debe especificarse formalmente la licencia bajo la cual se entrega el proyecto, cumpliendo con la Ley de Infogobierno.</p><h3 id="clausula-de-licencia-publica-general-gnu-gpl-v3" tabindex="-1">Cláusula de Licencia Pública General GNU (GPL v3): <a class="header-anchor" href="#clausula-de-licencia-publica-general-gnu-gpl-v3" aria-label="Permalink to &quot;Cláusula de Licencia Pública General GNU (GPL v3):&quot;">​</a></h3><blockquote><p><em>&quot;Este programa es software libre: puede redistribuirlo y/o modificarlo bajo los términos de la Licencia Pública General GNU publicada por la Free Software Foundation, ya sea la versión 3 de la Licencia, o cualquier versión posterior. Este programa se distribuye con la esperanza de que sea útil, pero SIN NINGUNA GARANTÍA.&quot;</em></p></blockquote><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-3" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 3 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-3" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 3&quot;">​</a></h2><p>Para la Evaluación 3 del Trimestre VI, el equipo consignará:</p><ol><li><strong>Manual de Usuario:</strong> En formato PDF encuadernado o digital, redactado en lenguaje amigable y profusamente ilustrado con capturas de pantalla guiadas.</li><li><strong>Manual del Sistema / Administrador:</strong> Con la arquitectura completa, guía de instalación técnica y procedimientos de respaldo de base de datos.</li><li><strong>CD / Pendrive con el Entregable Completo:</strong> Código fuente con licencia GPL, script de base de datos y ambos manuales digitales listos para entrega formal a la comunidad.</li></ol>',20))])}const A=l(m,[["render",p]]);export{P as __pageData,A as default};
